import {EFFECT_CSS} from './effects.js';
const effectStyle=document.createElement('style');effectStyle.textContent=EFFECT_CSS;document.head.append(effectStyle);
import {THEMES,FURINA_QUOTE,normalize,CATALOG,characterPreset,GAME_INFO,signatureForState} from './model.js';
import {renderCard,loadFonts} from './renderer.js';
import {createViewer} from './viewer.js';
import * as storage from './storage.js';
import {savePNG,saveHTML} from './export.js';
const $=s=>document.querySelector(s),form=$('#editorForm'),front=$('#frontCanvas'),back=$('#backCanvas');

let state=characterPreset('furina'),renderVersion=0,renderPromise=Promise.resolve(),renderPending=false,ready=false,records=[],savedId=null,saveTimer,toastTimer,uploadVersion=0;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
for(const button of document.querySelectorAll('[data-game]')){const badge=document.createElement('small');badge.className='game-count';badge.textContent=CATALOG.filter(c=>c.game===button.dataset.game).length;button.append(badge);}
const viewer=createViewer($('#card'),{onAuto(value){$('#autoRotate').setAttribute('aria-pressed',String(value));$('#autoRotate').innerHTML=value?'Ⅱ <span>회전 멈추기</span>':'↻ <span>자동 회전</span>'}});
$('#autoRotate').onclick=()=>viewer.toggleAuto();$('#flipCard').onclick=()=>viewer.flip();$('#resetView').onclick=()=>viewer.reset();
function setTab(name){for(const button of document.querySelectorAll('[data-tab]')){const on=button.dataset.tab===name;button.setAttribute('aria-selected',String(on));button.tabIndex=on?0:-1}for(const panel of document.querySelectorAll('[role=tabpanel]'))panel.hidden=panel.id!==name+'Panel'}
for(const button of document.querySelectorAll('[data-tab]')){button.onclick=()=>setTab(button.dataset.tab);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=['character','design','stats'],next=(tabs.indexOf(button.dataset.tab)+(e.key==='ArrowRight'?1:2))%3;setTab(tabs[next]);$('[data-tab='+tabs[next]+']').focus()}}
for(let i=0;i<4;i++){const row=document.createElement('div');row.className='stat-row';for(const key of ['label','value']){const input=document.createElement('input');input.name='stat_'+i+'_'+key;input.maxLength=key==='label'?14:16;input.setAttribute('aria-label',`스탯 ${i+1} ${key==='label'?'이름':'값'}`);row.append(input)}$('#statFields').append(row)}
function showState(){for(const control of form.elements){if(!control.name||!(control.name in state))continue;if(control.type==='checkbox')control.checked=state[control.name];else control.value=state[control.name]}state.stats.forEach((stat,i)=>{form.elements['stat_'+i+'_label'].value=stat.label;form.elements['stat_'+i+'_value'].value=stat.value});for(const button of document.querySelectorAll('[data-game]')){button.classList.toggle('selected',button.dataset.game===state.game);button.setAttribute('aria-pressed',String(button.dataset.game===state.game))}for(const button of document.querySelectorAll('[data-preset]')){button.classList.toggle('selected',button.dataset.preset===state.preset);button.setAttribute('aria-pressed',String(button.dataset.preset===state.preset))}for(const button of document.querySelectorAll('[data-theme]')){button.classList.toggle('selected',button.dataset.theme===state.theme);button.setAttribute('aria-pressed',String(button.dataset.theme===state.theme))}renderCharacters();$('#presetNote').textContent='일러스트 · 테마 자동 적용';showLabels();}
function showLabels(){const gear=signatureForState(state),char=CATALOG.find(c=>c.id===state.preset);$('#gearPreview').hidden=!gear;if(gear){$('#gearImage').src=gear.image;$('#gearName').textContent=gear.name;$('#gearType').textContent=gear.type;}$('#gearLabel').textContent=char.signature?.type||'장착 무기';$('#applySignature').disabled=!char.signature;$('#applySignature').textContent=char.signature?.type==='추천 무기'?'추천 무기 적용':'전용 장비 적용';$('.preview-area').style.setProperty('--scene','url("'+char.scene+'")');$('#sceneName').textContent=char.sceneLabel;$('#sceneDescription').textContent=char.sceneDescription;$('#previewTitle').textContent=state.name||'나의 캐릭터';$('#quoteCount').textContent=state.quote.length+' / 90';$('#quoteSource').textContent=state.quote===FURINA_QUOTE?'푸리나 · 한국어 첫 만남 대사':'원하는 대사를 직접 입력할 수 있어요.';form.elements.zoom.min=Math.round(char.view.zoom*.5);form.elements.zoom.max=char.view.zoom;form.elements.zoom.value=Math.min(state.zoom,char.view.zoom);$('#zoomValue').textContent=Math.round(Math.min(1,state.zoom/char.view.zoom)*100)+'%';$('#holoValue').textContent=state.holo+'%';$('#previewHoloValue').textContent=state.holo+'%';$('#previewHolo').value=state.holo;form.elements.holo.value=state.holo;for(const b of document.querySelectorAll('[data-holo]'))b.setAttribute('aria-pressed',String(Number(b.dataset.holo)===state.holo));$('#card').dataset.effect=state.effect||'holo';$('#card').style.setProperty('--power',state.holo/100);for(const layer of document.querySelectorAll('#card .sparkle'))layer.style.display=state.sparkle?'':'none';$('#stageAura').style.background=`radial-gradient(ellipse,${THEMES[state.theme].light}18,transparent 65%)`}
function requestRender(){renderVersion++;showLabels();if(!ready)return;document.body.dataset.renderStatus='loading';$('#card').setAttribute('aria-busy','true');if(!renderPending){renderPending=true;renderPromise=renderLoop();}}
async function renderLoop(){
 try{while(true){const version=renderVersion,snapshot=structuredClone(state);let result;try{result=await renderCard(snapshot)}catch(e){if(version!==renderVersion)continue;throw e}if(version!==renderVersion)continue;front.getContext('2d').clearRect(0,0,1000,1500);front.getContext('2d').drawImage(result.front,0,0);back.getContext('2d').clearRect(0,0,1000,1500);back.getContext('2d').drawImage(result.back,0,0);document.body.dataset.renderStatus='ready';$('#card').setAttribute('aria-label',snapshot.name+' 홀로그램 카드. 드래그 또는 방향키로 회전.');break}}
 catch(e){document.body.dataset.renderStatus='error';toast(e.message)}finally{renderPending=false;$('#card').setAttribute('aria-busy','false')}
}
function autosave(){clearTimeout(saveTimer);$('#saveStatus').innerHTML='<i></i> 저장 중';saveTimer=setTimeout(async()=>{try{await storage.put({id:'draft',state:structuredClone(state),savedId});$('#saveStatus').innerHTML='<i></i> 이 기기에 자동 저장'}catch{$('#saveStatus').textContent='자동 저장을 사용할 수 없어요'}},600)}
form.onsubmit=e=>e.preventDefault();form.addEventListener('input',e=>{const el=e.target,name=el.name;if(!name)return;if(name==='holo'){updateHolo(el.value);return;}if(name.startsWith('stat_')){const [,i,key]=name.split('_');state.stats[i][key]=el.value}else if(name in state)state[name]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;requestRender();autosave()});
function changeState(next){state=normalize({...next,holo:state.holo,effect:state.effect,sparkle:state.sparkle,ornament:state.ornament});savedId=null;showState();requestRender();autosave();viewer.reset()}
function searchKey(value){return String(value||'').normalize('NFKC').toLocaleLowerCase('ko').replace(/[\s·•.()「」\-]/g,'')}
function renderCharacters(){
 const list=$('#characterList'),scroll=list.scrollTop,q=searchKey($('#characterSearch').value),all=CATALOG.filter(c=>c.game===state.game);
 const chars=all.filter(c=>!q||[c.name,c.region,c.element,...(c.aliases||[])].some(x=>searchKey(x).includes(q)));
 $('#catalogCount').textContent=chars.length+' / '+all.length;
 $('#catalogNote').textContent='공식 일러스트와 설정에 맞는 배경이 적용돼요. 이름·소속으로 검색할 수 있어요.';
 list.replaceChildren();const fragment=document.createDocumentFragment();
 for(const char of chars){
  const b=document.createElement('button');b.type='button';b.className='character-option'+(char.id===state.preset?' selected':'');b.dataset.preset=char.id;b.setAttribute('aria-pressed',String(char.id===state.preset));
  const pic=document.createElement('span');pic.className='portrait '+char.theme;const im=new Image();im.loading='lazy';im.decoding='async';im.src=char.thumb||char.art;im.alt='';pic.append(im);
  const info=document.createElement('span'),name=document.createElement('b'),meta=document.createElement('small'),rarity=document.createElement('small');name.textContent=char.name;meta.textContent=char.element+' · '+char.region;rarity.className='rarity-badge';rarity.textContent=char.mascot?'✧ 마스코트':(char.rarity||'?')+'성'+(char.special?' · 기본 캐릭터':'');info.append(name,meta,rarity);
  const dot=document.createElement('span');dot.className='select-dot';dot.textContent='✓';b.append(pic,info,dot);
  b.onclick=()=>{uploadVersion++;changeState(characterPreset(char.id));};fragment.append(b);
 }
 if(!chars.length){const e=document.createElement('p');e.className='field-note';e.textContent='검색 결과가 없어요. 다른 이름이나 소속으로 찾아보세요.';fragment.append(e)}list.append(fragment);list.scrollTop=scroll;
}
function updateHolo(value){state.holo=Math.max(0,Math.min(100,Number(value)||0));showLabels();autosave()}
$('#previewHolo').addEventListener('input',e=>updateHolo(e.target.value));for(const b of document.querySelectorAll('[data-holo]'))b.onclick=()=>updateHolo(b.dataset.holo);
$('#characterSearch').addEventListener('input',()=>{$('#characterList').scrollTop=0;renderCharacters()});
for(const button of document.querySelectorAll('[data-game]'))button.onclick=()=>{if(state.game===button.dataset.game)return;uploadVersion++;$('#characterSearch').value='';$('#characterList').scrollTop=0;const preferred={genshin:'furina',starrail:'hsr-1310',wuwa:'jinhsi',blue:'aru'};const first=CATALOG.find(c=>c.id===preferred[button.dataset.game])||CATALOG.find(c=>c.game===button.dataset.game);changeState(characterPreset(first.id))};
for(const button of document.querySelectorAll('[data-theme]'))button.onclick=()=>{state.theme=button.dataset.theme;for(const b of document.querySelectorAll('[data-theme]')){b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))}requestRender();autosave()};
$('#resetArt').onclick=()=>{const v=characterPreset(state.preset);for(const k of ['zoom','offsetX','offsetY'])state[k]=v[k];showState();requestRender();autosave()};
$('#applySignature').onclick=()=>{const char=CATALOG.find(c=>c.id===state.preset);if(!char.signature)return;state.weapon=char.signature.name;state.showWeapon=true;showState();requestRender();autosave()};
async function exportReady(){await renderPromise;if(document.body.dataset.renderStatus!=='ready')throw new Error('카드가 완성될 때까지 잠시 기다려주세요.')}
function busy(button,value){button.disabled=value;button.setAttribute('aria-busy',String(value))}
$('#downloadPNG').onclick=async()=>{const b=$('#downloadPNG');busy(b,true);try{await exportReady();await savePNG(front,state);toast('PNG 이미지를 저장했어요.')}catch(e){toast(e.message)}finally{busy(b,false)}};
$('#downloadHTML').onclick=async()=>{const b=$('#downloadHTML');busy(b,true);try{await exportReady();saveHTML(front,back,state);toast('움직이는 카드를 저장했어요. HTML 파일을 브라우저에서 열어보세요.')}catch(e){toast(e.message)}finally{busy(b,false)}};
async function refreshRecords(){const all=await storage.getAll();records=all.filter(r=>r.id!=='draft').sort((a,b)=>b.created-a.created);$('#galleryCount').textContent=records.length;return all}
$('#saveCard').onclick=async()=>{const b=$('#saveCard');busy(b,true);try{await exportReady();await refreshRecords();if(!savedId&&records.length>=24){toast('보관함에는 24장까지 담을 수 있어요. 카드를 파일로 저장한 뒤 보관함을 정리해주세요.');return}const thumb=document.createElement('canvas');thumb.width=240;thumb.height=360;thumb.getContext('2d').drawImage(front,0,0,240,360);const record={id:savedId||crypto.randomUUID(),state:structuredClone(state),thumb:thumb.toDataURL('image/jpeg',.85),created:Date.now()};await storage.put(record);savedId=record.id;await refreshRecords();autosave();toast('내 보관함에 카드를 담았어요.')}catch(e){toast('카드를 보관하지 못했어요. 저장 공간을 확인하거나 파일로 저장해주세요.')}finally{busy(b,false)}};
function renderGallery(){const grid=$('#galleryGrid');grid.replaceChildren();if(!records.length){const empty=document.createElement('div');empty.className='gallery-empty';const star=document.createElement('span');star.textContent='✧';empty.append(star,document.createTextNode('아직 첫 번째 카드를 기다리고 있어요.'),document.createElement('br'),document.createTextNode('마음에 드는 카드를 만들고 ‘카드 보관’을 눌러주세요.'));grid.append(empty);return}for(const record of records){const item=document.createElement('div');item.className='gallery-item';const button=document.createElement('button');button.className='gallery-open';const img=new Image();img.src=record.thumb;img.alt=record.state.name+' 저장 카드';const name=document.createElement('b');name.textContent=record.state.name||'나의 캐릭터';const sub=document.createElement('small');sub.textContent=THEMES[record.state.theme]?.label||'내 카드';button.append(img,name,sub);button.onclick=()=>{if(!CATALOG.some(c=>c.id===record.state.preset)){toast('현재 선택 목록에서 제외된 캐릭터예요. 저장된 미리보기는 보관돼요.');return;}uploadVersion++;state=normalize(record.state);savedId=record.id;showState();requestRender();autosave();viewer.reset();$('#galleryDialog').close();toast('저장한 카드를 불러왔어요.')};const del=document.createElement('button');del.className='delete-card';del.textContent='×';del.setAttribute('aria-label',name.textContent+' 카드 삭제');del.onclick=async()=>{try{await storage.remove(record.id);if(savedId===record.id)savedId=null;await refreshRecords();renderGallery();toast('보관함에서 삭제했어요.')}catch{toast('삭제하지 못했어요. 다시 시도해주세요.')}};item.append(button,del);grid.append(item)}}
$('#openGallery').onclick=async()=>{try{await refreshRecords();renderGallery();$('#galleryDialog').showModal()}catch{toast('이 브라우저에서는 보관함을 사용할 수 없어요. 파일 저장을 이용해주세요.')}};
$('#openHelp').onclick=()=>$('#helpDialog').showModal();for(const button of document.querySelectorAll('[data-close]'))button.onclick=()=>$('#'+button.dataset.close).close();for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
async function init(){try{const all=await refreshRecords();const draft=all.find(r=>r.id==='draft');if(draft?.state){state=normalize(draft.state);savedId=records.some(r=>r.id===draft.savedId)?draft.savedId:null}}catch{$('#saveStatus').textContent='자동 저장을 사용할 수 없어요'}showState();try{await loadFonts()}catch{toast('기본 글꼴로 카드를 표시해요.')}ready=true;requestRender()}
init();
